/**
 * @type {import('next').NextConfig}
 */
const nextConfig = {
  /* config options here */
}

module.exports = nextConfig

export const config = {}
// `config.amp` is defined after `config` is exported
config.amp = true

// `config.amp` contains a dynamic expression
export const config = {
  amp: 1 + 1 > 2,
}

export const config = {
  amp: true,
}

export const config = {
  amp: false,
}

// `config.runtime` contains a dynamic expression
export const config = {
  runtime: `node${'js'}`,
}

export const config = {
  runtime: 'nodejs',
}
export const config = {
  runtime: `edge`,
}
